    {
        //Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Actor actor = SpawnRegistry.seedActor(field, row, col, rand);
                if(actor instanceof Plants plant) {
                    plants.add(plant);
                }
                else if(actor != null) {
