    /**
     * Show the current status of the field.
     * @param snapshot The current simulation state.
     */
    public void showStatus(SimulationSnapshot snapshot)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        Field field = snapshot.getField();
        stepLabel.setText(STEP_PREFIX + snapshot.getSteps() );
        stats.reset();
        infectedPopulationCount = 0;

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Location location = new Location(row, col);
                Actor surfaceActor = field.getTraversableActorAt(location);
                Actor occupant = field.getOccupantAt(location);
                Actor actor = field.getActorAt(row, col);
                if(actor != null) {
                    stats.incrementCount(surfaceActor);
                    stats.incrementCount(occupant);
                    fieldView.drawMark(col, row, getColor(actor.getKind()));
                    if(actor instanceof Animal animal && !animal.getHealth()){
                        infectedPopulationCount ++;
                    }
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();
        if(snapshot.isDay()){
            dayLabel.setText( DAY_PREFIX+ snapshot.getNumberOfDays() + "      Time: " + timer.getTime(snapshot.getSteps()) + "   It is Day Time. ");
        }else{
            dayLabel.setText( DAY_PREFIX+ snapshot.getNumberOfDays() + "      Time: " + timer.getTime(snapshot.getSteps()) + "   It is Night Time ");
        }

        infoLabel.setText(" " + snapshot.getWeather() + "        " + INFECTION_PREFIX + infectedPopulationCount );
        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

    private Map<ActorKind, Color> loadDefaultColors()
    {
        Properties properties = ConfigLoader.loadProperties("config/ui.properties");
        Map<ActorKind, Color> loadedColors = new EnumMap<>(ActorKind.class);
        for(ActorKind kind : ActorKind.values()) {
            String key = "ui.color." + kind.name();
            loadedColors.put(kind, ConfigLoader.requiredColor(properties, key));
        }
        return loadedColors;
    }

