  9	/**
 10	 * A simple predator-prey simulator of a safari, based on a rectangular field
 11	 * containing lions, cheetahs, jaguars, zebras, gazelles, hunters and grass.
 12	 *
 13	 * @version 2022.03.01
 14	 */
 15	public class Simulator
 16	{
 17	    // Constants representing configuration information for the simulation.
 18	    private static final Properties SIMULATOR_PROPERTIES = ConfigLoader.loadProperties("config/simulator.properties");
 19	    // The default width for the grid.
 20	    private static final int DEFAULT_WIDTH = loadDefaultWidth();
 21	    // The default depth of the grid.
 22	    private static final int DEFAULT_DEPTH = loadDefaultDepth();
 23	
 24	    // List of animals and plants which can not be stood on in the field.
 25	    private List<Actor> animals;
 26	    // List of plants that can be stood on in the field.
 27	    private List<Actor> plants;
 28	    // The current state of the field.
 29	    private Field field;
 30	    // The current step of the simulation.
 31	    private int step;
 32	
 33	    private boolean isDay;
 34	    //check the random weather method and the use of the random weather method in one step method
 35	    private Weather weather;
 36	    private int numberOfDays;
 37	    private static final Random rand = Randomizer.getRandom();
 38	    // Cached viability checker used to avoid coupling the model to the view.
 39	    private final FieldStats viabilityStats;
 40	    /**
 41	     * Construct a simulation field with default size.
 42	     */
 43	    public Simulator()
 44	    {
 45	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
 46	    }
 47	
 48	    /**
 49	     * Create a simulation field with the given size.
 50	     * @param depth Depth of the field. Must be greater than zero.
 51	     * @param width Width of the field. Must be greater than zero.
 52	     */
 53	    public Simulator(int depth, int width)
 54	    {
 55	        if(width <= 0 || depth <= 0) {
 56	            System.out.println("The dimensions must be greater than zero.");
 57	            System.out.println("Using default values.");
 58	            depth = DEFAULT_DEPTH;
 59	            width = DEFAULT_WIDTH;
 60	        }
 61	
 62	        animals = new ArrayList<>();
 63	        plants = new ArrayList<>();
 64	        field = new Field(depth, width);
 65	        viabilityStats = new FieldStats();
 66	
 67	        // Setup a valid starting point.
 68	        reset();
 69	    }
 70	
 71	    /**
 72	     * Run the simulation from its current state for a reasonably long period,
 73	     * (4000 steps).
 74	     */
 75	    public void runLongSimulation()
 76	    {
 77	        simulate(4000);
 78	    }
 79	
 80	    /**
 81	     * Run the simulation from its current state for the given number of steps.
 82	     * Stop before the given number of steps if it ceases to be viable.
 83	     * @param numSteps The number of steps to run for.
 84	     */
 85	    public void simulate(int numSteps)
 86	    {
 87	        for(int step = 1; step <= numSteps && isViable(); step++) {
 88	            simulateOneStep();
 89	            //delay(120);   // uncomment this to run more slowly
 90	        }
 91	    }
 92	
 93	    /**
 94	     * Run the simulation from its current state for a single step.
 95	     * Iterate over the whole field updating the state of each
 96	     * actor in the field. One  day lasts 4 steps, with day and night alternating every 2 steps.
 97	     * Buttons are disabled before the simulation starts and enabled after the simulation is finsihed.
 98	     */
 99	    public void simulateOneStep()
100	    {
101	        step++;
102	        if(step % 2 == 0){
103	            isDay  = !isDay;
104	            if(isDay){
105	                numberOfDays++;
106	            }
107	        }
108	
109	        // Provide space for newborn actors.
110	        List<Actor> newAnimals = new ArrayList<>();  
111	        List<Actor> newGrass = new ArrayList<>();  
112	
113	        getRandomWeather();
114	        while(!isDay && weather == weather.SUNNY){
115	            getRandomWeather();
116	        }
117	        // Let all actors act.
118	        //iterates through all the animals and hunters
119	
120	        for(Iterator<Actor> it = animals.iterator(); it.hasNext(); ) {
121	            Actor animal = it.next();
122	            animal.act(newAnimals,this);
123	            if(! animal.isActive()) {
124	                it.remove();
125	            }
126	        }
127	        animals.addAll(newAnimals);
128	        for(Iterator<Actor> it = plants.iterator(); it.hasNext(); ) {
129	            Actor plants = it.next();
130	            plants.act(newGrass,this);
131	            if(! plants.isActive()) {
132	                it.remove();
133	            }
134	        }
135	        plants.addAll(newGrass);
136	
137	        if(step % 500 == 0){
138	            introduceInfection();
139	        }
140	
141	        viabilityStats.reset();
142	    }
143	
144	    /**
145	     * Reset the simulation to a starting position.
146	     */
147	    public void reset()
148	    {
149	        step = 0;
150	        animals.clear();
151	        plants.clear();
152	        populate();
153	        isDay = true;
154	        numberOfDays = 0;
155	        getRandomWeather();
156	        viabilityStats.reset();
157	    }
158	
159	    /**
160	     * Randomly populate the field with all the actors.
161	     */
162	    private void populate()
163	    {
164	        //Random rand = Randomizer.getRandom();
165	        field.clear();
166	        for(int row = 0; row < field.getDepth(); row++) {
167	            for(int col = 0; col < field.getWidth(); col++) {
168	                Actor actor = SpawnRegistry.seedActor(field, row, col, rand);
169	                if(actor instanceof Plants plant) {
170	                    plants.add(plant);
171	                }
172	                else if(actor != null) {
173	                    animals.add(actor);
174	                }
175	                // else leave the location empty.
176	            }
177	        }
178	    }
179	
180	    /**
181	     * Pause for a given time.
182	     * @param millisec  The time to pause for, in milliseconds
183	     */
184	    private void delay(int millisec)
185	    {
186	        try {
187	            Thread.sleep(millisec);
188	        }
189	        catch (InterruptedException ie) {
190	            // wake up
191	        }
192	    }
193	
194	    /**
195	     * Return the total number of steps the simulation has run for.
196	     * @return The total steps the simualtion ran for.
197	     */
198	    public int getSteps(){
199	        return step;
200	    }
201	
202	    /**
203	     * Randomly generates a weather from the enum class.
204	     * @return A random weather.
205	     */
206	    private void getRandomWeather(){
207	        int value = rand.nextInt(weather.values().length);
208	        weather = weather.values()[value];
209	    }
210	
211	    /**
212	     * Returns the List which contains all the plants in the simualtion.
213	     * @return A list of all the alive plants in the simulation.
214	     */
215	    public List<Actor> getGrass(){
216	        return plants;
217	    }  
218	
219	    /**
220	     * Chooses a random animal to infect. This method is automatically called after 100 steps,
221	     * or it can be called by pressing the introduce infection button.
222	     */
223	    public void introduceInfection(){
224	        if(animals.size() != 0){
225	            int value = rand.nextInt(animals.size());
226	            if(animals.get(value) instanceof Animal){
227	                Animal animal = (Animal)animals.get(value);
228	                animal.setUnhealthy();
229	            }
230	        }
231	    }
232	    
233	    /**
234	     * Returns the number of days.
235	     * @return  number of days.
236	     */
237	    public int  getNoOfDays(){
238	        return numberOfDays;
239	    }
240	    
241	    /**
242	     * Returns if it is currently day or night.
243	     * @return true if it is day.
244	     */
245	    public boolean  isDay(){
246	        return isDay;
247	    }
248	    
249	    /**
250	     * Return the weather in the simulation.
251	     * @return weather The current weather in the simulation.
252	     */
253	    public Weather getWeather(){
254	        return weather;
255	    }
256	
257	    /**
258	     * Determine whether the simulation should continue running.
259	     * @return true if there is more than one species alive.
260	     */
261	    public boolean isViable()
262	    {
263	        return viabilityStats.isViable(field);
264	    }
265	
266	    /**
267	     * Create an immutable snapshot of the current simulation state for the UI.
268	     * @return the current simulation snapshot.
269	     */
270	    public SimulationSnapshot createSnapshot()
271	    {
272	        return new SimulationSnapshot(field, step, numberOfDays, isDay, weather);
273	    }
